import{_ as t,o as a,c as r,ag as n}from"./chunks/framework.B9unkguw.js";const p=JSON.parse('{"title":"GeoMap Engine (Tech Preview)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/qgc-user-guide/fly_view/geoview.md","filePath":"zh/qgc-user-guide/fly_view/geoview.md"}'),i={name:"zh/qgc-user-guide/fly_view/geoview.md"};function o(l,e,s,d,h,g){return a(),r("div",null,e[0]||(e[0]=[n('<h1 id="geomap-engine-tech-preview" tabindex="-1">GeoMap Engine (Tech Preview) <a class="header-anchor" href="#geomap-engine-tech-preview" aria-label="Permalink to &quot;GeoMap Engine (Tech Preview)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The GeoMap engine is an experimental technology preview and is under active development. Expect missing features and rough edges. It is too early to report issues against this feature — there is still too much work left to do.</p></div><p>The GeoMap engine is a new map engine for QGroundControl that renders a single, seamless 2D/3D map: satellite/street imagery draped over real terrain elevation, with Google Earth-style camera controls. When enabled it replaces the map in the <a href="./fly_view.html">Fly View</a>, displaying your vehicles, the planned mission (with waypoint markers, connecting path, and drop lines showing each waypoint&#39;s height above the terrain), the flown flight path, the launch location, and the ground station position — all in true 3D.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Map interaction (click-to-goto, orbit, ROI, and other map click actions) is available in 2D mode only; 3D mode is currently view-only. All other Fly View controls (arm, takeoff, guided actions, instruments, and so on) work as usual.</p></div><p>The long-term goal is for the GeoMap engine to eventually replace all map usage throughout QGroundControl, including the Plan view, providing one consistent 2D/3D map experience everywhere.</p><h2 id="enabling-the-geomap-engine" tabindex="-1">Enabling the GeoMap Engine <a class="header-anchor" href="#enabling-the-geomap-engine" aria-label="Permalink to &quot;Enabling the GeoMap Engine&quot;">​</a></h2><p>The GeoMap engine is disabled by default. To enable it, go to <strong>Application Settings &gt; Fly View</strong> and turn on <strong>Use GeoMap engine (preview)</strong>, then restart QGroundControl. After the restart the Fly View map is rendered by the GeoMap engine.</p><h2 id="view-controls" tabindex="-1">View Controls <a class="header-anchor" href="#view-controls" aria-label="Permalink to &quot;View Controls&quot;">​</a></h2><p>Camera gestures follow Google Earth semantics: the ground point under the cursor when a gesture starts stays pinned under the cursor throughout the gesture.</p><ul><li><strong>Mouse:</strong><ul><li><strong>Pan</strong>: Left-drag. The terrain point you grabbed follows the cursor.</li><li><strong>Orbit (rotate)</strong>: Right-drag or middle-drag. The view rotates around the ground point you pressed on (marked by a pivot ring): left/right changes heading, up/down changes tilt between top-down and near-horizontal.</li><li><strong>Zoom</strong>: Scroll wheel or trackpad scroll. Zooms toward/away from the point under the cursor.</li></ul></li><li><strong>Touch:</strong><ul><li><strong>Pan</strong>: Single-finger drag.</li><li><strong>Zoom</strong>: Two-finger pinch, centered on the pinch point.</li><li><strong>Rotate</strong>: Two-finger twist.</li></ul></li></ul><h3 id="keyboard-support" tabindex="-1">Keyboard Support <a class="header-anchor" href="#keyboard-support" aria-label="Permalink to &quot;Keyboard Support&quot;">​</a></h3><p>Keyboard modifiers provide alternatives to the multi-button mouse gestures (useful with one-button mice and trackpads):</p><ul><li><strong>Shift + left-drag</strong>: Orbit, same as right/middle-drag.</li><li><strong>Ctrl + left-drag</strong>: First-person look. The camera stays in place and the view rotates, like turning your head — drag toward where you want to look. On macOS both <strong>Ctrl</strong> and <strong>Cmd</strong> work.</li></ul><h3 id="_2d-3d-modes" tabindex="-1">2D/3D Modes <a class="header-anchor" href="#_2d-3d-modes" aria-label="Permalink to &quot;2D/3D Modes&quot;">​</a></h3><ul><li>The <strong>3D/2D</strong> button in the top-right switches between modes. Switching animates the camera tilt and flattens/raises the terrain; 2D mode behaves like a traditional top-down map (tilt is locked).</li><li>The <strong>compass</strong> button rotates with the current heading; click it to animate the view back to north-up.</li></ul><h2 id="imagery-and-terrain" tabindex="-1">Imagery and Terrain <a class="header-anchor" href="#imagery-and-terrain" aria-label="Permalink to &quot;Imagery and Terrain&quot;">​</a></h2><p>The GeoMap engine drapes the same map imagery you have selected in <strong>Application Settings &gt; Maps</strong> over its terrain surface. Terrain elevation comes from the <a href="https://registry.opendata.aws/terrain-tiles/" target="_blank" rel="noreferrer">Mapzen/Tilezen Terrain Tiles</a> dataset, which combines the following sources:</p><ul><li>ArcticDEM terrain data DEM(s) were created from DigitalGlobe, Inc., imagery and funded under National Science Foundation awards 1043681, 1559691, and 1542736</li><li>Australia terrain data © Commonwealth of Australia (Geoscience Australia) 2017</li><li>Austria terrain data © offene Daten Österreichs – Digitales Geländemodell (DGM) Österreich</li><li>Canada terrain data contains information licensed under the Open Government Licence – Canada</li><li>Europe terrain data produced using Copernicus data and information funded by the European Union – EU-DEM layers</li><li>Global ETOPO1 terrain data U.S. National Oceanic and Atmospheric Administration</li><li>Mexico terrain data source: INEGI, Continental relief, 2016</li><li>New Zealand terrain data Copyright 2011 Crown copyright (c) Land Information New Zealand and the New Zealand Government (All rights reserved)</li><li>Norway terrain data © Kartverket</li><li>United Kingdom terrain data © Environment Agency copyright and/or database right 2015. All rights reserved</li><li>United States 3DEP (formerly NED) and global GMTED2010 and SRTM terrain data courtesy of the U.S. Geological Survey</li></ul>',18)]))}const u=t(i,[["render",o]]);export{p as __pageData,u as default};
